import test from 'node:test'
import assert from 'node:assert/strict'
import {createTeeTemplate} from '../data/templates.js'
import {inspectIndustrialMarkerCutWorkflow20261028} from './industrialMarkerCutWorkflow20261028.mjs'
import {qualifyIndustrialCutterStudy20261028 as qualify} from './industrialCutterQualification20261028.mjs'

// The six-size CUT source is generated by EXO, not a manually approved record.
const garment=createTeeTemplate()
for(const piece of garment.pieces){
 piece.notches=[];piece.internalLines=[];piece.buttonholes=[]
 piece.marker={nap:'one-way',allowCrossGrain:false};piece.grainAngleDeg=0
}
const workflow=inspectIndustrialMarkerCutWorkflow20261028(garment,{maxCandidates:50000})
assert.equal(workflow.ok,true,JSON.stringify(workflow.issues).slice(0,500))
assert.equal(workflow.rows.length,6)
const row=workflow.rows[0]
const original=row.cutterStudy.records[0].physicalCutPathMm
const profile={profileId:'fixture',manufacturer:'Synthetic',model:'NoMachine',bedWidthMm:2000,bedLengthMm:100000,supportsNotches:true,supportsDrills:true}
const evidence={calibration:{referenceLengthMm:100,measuredLengthMm:100,operatorId:'fixture',measuredAt:'2026-10-31'},receiverAcceptance:{accepted:true,application:'SyntheticFixture',version:'v1',operatorId:'fixture',evidenceFiles:['synthetic-only.txt']}}
const inspect=path=>qualify({...row.cutterStudy,records:row.cutterStudy.records.map((record,i)=>i===0?{...record,physicalCutPathMm:path}:record)},row.markTransfer,profile,evidence)
const p=(xMm,yMm)=>({xMm,yMm})
const refused=(path,code)=>{
 const result=inspect(path)
 assert.equal(result.ok,false,JSON.stringify(result))
 assert(result.issues.some(issue=>issue.code===code),JSON.stringify(result.issues))
 assert.equal(result.cuttingAuthorized,false)
 assert.equal(result.machineReady,false)
 assert.equal(result.manufacturingApproved,false)
}

test('actual six-size generated CUT contour remains locally inspectable, never authorized',()=>{
 const result=inspect(original)
 assert.equal(result.ok,true,JSON.stringify(result.issues))
 assert.equal(result.cuttingAuthorized,false)
})
test('nonzero-area crossing CUT contour fails closed',()=>{
 refused([p(10,10),p(70,70),p(10,65),p(80,10),p(10,10)],'CUT_CONTOUR_SELF_INTERSECTION')
})
test('closed nonadjacent vertex touch fails closed',()=>{
 refused([p(10,10),p(60,10),p(60,60),p(30,30),p(10,60),p(30,30),p(10,10)],'CUT_CONTOUR_SELF_INTERSECTION')
})
test('overlapping CUT edge fails closed',()=>{
 refused([p(10,10),p(60,10),p(60,60),p(10,60),p(10,30),p(40,30),p(40,10),p(10,10)],'CUT_CONTOUR_SELF_INTERSECTION')
})
test('simple concave closed CUT contour remains inspectable without authorization',()=>{
 const result=inspect([p(10,10),p(70,10),p(70,60),p(40,40),p(10,60),p(10,10)])
 assert.equal(result.ok,true,JSON.stringify(result.issues))
 assert.equal(result.cuttingAuthorized,false)
})
test('untrusted oversized CUT contour cannot trigger unbounded pairwise inspection',()=>{
 const path=Array.from({length:4096},(_,i)=>p(10+i/100,10))
 path.push(p(10,10))
 refused(path,'INVALID_CUT_POINTS')
})
